        #[ignore]
        fn reader_munges() {
            let mut reader = Xorcism::new(KEY).reader(INPUT.as_bytes());
            let mut buf = Vec::with_capacity(INPUT.len());
            let bytes_read = reader.read_to_end(&mut buf).unwrap();
            assert_eq!(bytes_read, INPUT.len());
            assert_eq!(buf, EXPECT);
        }

