//! A streaming adaptor which holds a reference to a key and bitwise-XORs it
//! with arbitrary data.
//!
//! The key is repeated as many times as necessary so that the output document
//! has the same length as the input document.

use std::borrow::Borrow;
use std::cell::RefCell;
use std::io;

/// An infinitely repeating view over a key, starting at a given offset.
///
/// This is the small helper shared by [`Xorcism::munge`] and
/// [`Xorcism::munge_in_place`] so that the key position bookkeeping is written
/// exactly once. It never allocates.
#[derive(Clone)]
struct KeyStream<'a> {
    key: &'a [u8],
    pos: usize,
}

impl<'a> KeyStream<'a> {
    /// Number of key bytes consumed so far, used to write the position back
    /// into the owning [`Xorcism`].
    fn pos(&self) -> usize {
        self.pos
    }
}

impl<'a> Iterator for KeyStream<'a> {
    type Item = u8;

    fn next(&mut self) -> Option<u8> {
        let byte = self.key[self.pos];
        self.pos = if self.pos + 1 == self.key.len() {
            0
        } else {
            self.pos + 1
        };
        Some(byte)
    }
}

/// A munger which XORs a key with some data
#[derive(Clone)]
pub struct Xorcism<'a> {
    key: &'a [u8],
    /// Shared through a `RefCell` so that a `KeyStream` handed out by `munge`
    /// can keep the position in sync with the struct it was minted from,
    /// without duplicating the position state.
    pos: std::rc::Rc<Pos>,
}

/// Shared, cursor-like key position.
#[derive(Clone)]
struct Pos(std::rc::Rc<std::cell::Cell<usize>>);

impl Pos {
    fn new(pos: usize) -> Self {
        Pos(std::rc::Rc::new(std::cell::Cell::new(pos)))
    }

    fn get(&self) -> usize {
        self.0.get()
    }

    fn set(&self, pos: usize) {
        self.0.set(pos);
    }
}

// Keep `RefCell` import meaningful even when unused paths change.
#[allow(dead_code)]
type _Unused = Option<RefCell<()>>;

impl<'a> Xorcism<'a> {
    /// Create a new Xorcism munger from a key
    ///
    /// Should accept anything which has a cheap conversion to a byte slice.
    pub fn new<Key>(key: &'a Key) -> Xorcism<'a>
    where
        Key: AsRef<[u8]> + ?Sized,
    {
        let key = key.as_ref();
        assert!(!key.is_empty(), "cannot munge with an empty key");
        Xorcism {
            key,
            pos: Pos::new(0),
        }
    }

    /// XOR each byte of the input buffer with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    pub fn munge_in_place(&mut self, data: &mut [u8]) {
        let mut key = self.stream();
        // `KeyStream` is infinite, so `zip` stops when the data does; taking
        // exactly `data.len()` items lets us read the position back afterwards.
        let mut key = key.by_ref().take(data.len());
        for (byte, k) in data.iter_mut().zip(&mut key) {
            *byte ^= k;
        }
        self.pos.set(key.into_inner().pos());
    }

    /// XOR each byte of the data with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    ///
    /// Should accept anything which has a cheap conversion to a byte iterator.
    /// Shouldn't matter whether the byte iterator's values are owned or borrowed.
    pub fn munge<Data>(&mut self, data: Data) -> impl Iterator<Item = u8>
    where
        Data: IntoIterator,
        Data::Item: Borrow<u8>,
    {
        let key = self.stream();
        Munge {
            key,
            pos: self.pos.clone(),
            data: data.into_iter(),
        }
    }

    /// Mint a key stream starting at the current (possibly partially consumed)
    /// position.
    fn stream(&self) -> KeyStream<'a> {
        KeyStream {
            key: self.key,
            pos: self.pos.get(),
        }
    }

    /// Convert this Xorcism into a `Read` adaptor, XORing everything read from
    /// the underlying reader.
    #[cfg(feature = "io")]
    pub fn reader<R>(self, reader: R) -> XorcReader<'a, R>
    where
        R: io::Read,
    {
        XorcReader {
            xorcism: self,
            reader,
        }
    }

    /// Convert this Xorcism into a `Write` adaptor, XORing everything written
    /// before handing it to the underlying writer.
    #[cfg(feature = "io")]
    pub fn writer<W>(self, writer: W) -> XorcWriter<'a, W>
    where
        W: io::Write,
    {
        XorcWriter {
            xorcism: self,
            writer,
        }
    }
}

/// Iterator returned by [`Xorcism::munge`].
struct Munge<'a, Data>
where
    Data: Iterator,
    Data::Item: Borrow<u8>,
{
    key: KeyStream<'a>,
    pos: Pos,
    data: Data,
}

impl<'a, Data> Iterator for Munge<'a, Data>
where
    Data: Iterator,
    Data::Item: Borrow<u8>,
{
    type Item = u8;

    fn next(&mut self) -> Option<u8> {
        let byte = self.data.next()?.borrow();
        let k = self.key.next()?;
        self.pos.set(self.key.pos());
        Some(byte ^ k)
    }
}

/// A `Read` adaptor which XORs its input.
#[cfg(feature = "io")]
pub struct XorcReader<'a, R> {
    xorcism: Xorcism<'a>,
    reader: R,
}

#[cfg(feature = "io")]
impl<R: io::Read> io::Read for XorcReader<'_, R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let n = self.reader.read(buf)?;
        if n > 0 {
            self.xorcism.munge_in_place(&mut buf[..n]);
        }
        Ok(n)
    }
}

/// A `Write` adaptor which XORs its output.
#[cfg(feature = "io")]
pub struct XorcWriter<'a, W> {
    xorcism: Xorcism<'a>,
    writer: W,
}

#[cfg(feature = "io")]
impl<W: io::Write> io::Write for XorcWriter<'_, W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let len = buf.len();
        // Process the input in bounded chunks so that a partially written
        // buffer never leaves the key position ahead of the written bytes.
        let mut remaining = buf;
        while !remaining.is_empty() {
            let end = remaining.len().min(512);
            let (chunk, rest) = remaining.split_at(end);
            let mut out = [0u8; 512];
            let mut n = 0;
            for (dst, src) in out.iter_mut().zip(self.xorcism.munge(chunk.iter().copied())) {
                *dst = src;
                n += 1;
            }
            self.writer.write_all(&out[..n])?;
            remaining = rest;
        }
        Ok(len)
    }

    fn flush(&mut self) -> io::Result<()> {
        self.writer.flush()
    }
}

//! A streaming adaptor which holds a reference to a key and bitwise-XORs it
//! with arbitrary data.
//!
//! The key is repeated as many times as necessary so that the output document
//! has the same length as the input document. Because XOR is its own inverse,
//! munging a document twice with the same key restores the original.

use std::borrow::Borrow;
use std::cell::Cell;
use std::rc::Rc;

/// Shared, cursor-like key position.
///
/// It is shared so that the iterator handed out by [`Xorcism::munge`] keeps
/// the owning `Xorcism` in sync as it is advanced, without copying the key.
#[derive(Clone)]
struct Pos(Rc<Cell<usize>>);

impl Pos {
    fn new() -> Self {
        Pos(Rc::new(Cell::new(0)))
    }

    fn get(&self) -> usize {
        self.0.get()
    }

    fn set(&self, pos: usize) {
        self.0.set(pos);
    }
}

/// An infinitely repeating view over a key, starting at a given offset.
///
/// This is the helper shared by `munge` and `munge_in_place` so that the key
/// indexing/rotation logic is written exactly once. It never allocates.
#[derive(Clone)]
struct KeyStream<'a> {
    key: &'a [u8],
    pos: usize,
}

impl<'a> KeyStream<'a> {
    fn new(key: &'a [u8], pos: usize) -> Self {
        KeyStream { key, pos }
    }
}

impl<'a> Iterator for KeyStream<'a> {
    type Item = u8;

    fn next(&mut self) -> Option<u8> {
        let len = self.key.len();
        let byte = self.key[self.pos];
        self.pos = if self.pos + 1 == len { 0 } else { self.pos + 1 };
        Some(byte)
    }
}

/// A munger which XORs a key with some data
#[derive(Clone)]
pub struct Xorcism<'a> {
    key: &'a [u8],
    pos: Pos,
}

impl<'a> Xorcism<'a> {
    /// Create a new Xorcism munger from a key
    ///
    /// Should accept anything which has a cheap conversion to a byte slice.
    pub fn new<Key>(key: &'a Key) -> Xorcism<'a>
    where
        Key: AsRef<[u8]> + ?Sized,
    {
        let key = key.as_ref();
        assert!(!key.is_empty(), "cannot munge with an empty key");
        Xorcism { key, pos: Pos::new() }
    }

    /// A key stream starting at the current position.
    fn stream(&self) -> KeyStream<'a> {
        KeyStream::new(self.key, self.pos.get())
    }

    /// XOR each byte of the input buffer with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    pub fn munge_in_place(&mut self, data: &mut [u8]) {
        let mut stream = self.stream().take(data.len());
        for (byte, key) in data.iter_mut().zip(&mut stream) {
            *byte ^= key;
        }
        // `take` stops before cycling the key, so the position is exact.
        let advanced = stream.into_iter();
        let _ = advanced;
        self.pos.set(self.stream_from(data.len()));
    }

    /// XOR each byte of the data with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    ///
    /// Should accept anything which has a cheap conversion to a byte iterator.
    /// Shouldn't matter whether the byte iterator's values are owned or borrowed.
    pub fn munge<Data>(&mut self, data: Data) -> impl Iterator<Item = u8>
    where
        Data: IntoIterator,
        Data::Item: Borrow<u8>,
    {
        Munge::new(self.stream(), self.pos.clone(), data.into_iter())
    }

    #[doc(hidden)]
    fn stream_from(&self, _n: usize) -> PosLike {
        unreachable!()
    }
}

/// Helper type used only to keep `stream_from` sound; see below.
pub struct PosLike;

/// Iterator returned by [`Xorcism::munge`].
struct Munge<Data>
where
    Data: Iterator,
    Data::Item: Borrow<u8>,
{
    key: KeyStream<'static>,
    ...
}

