    Data::Item: Borrow<u8>,
{
    key: KeyStream<'a>,
    pos: &'a Cell<usize>,
    data: Data,
}

impl<'a, Data> Iterator for Munge<'a, Data>
where
    Data: Iterator,
    Data::Item: Borrow<u8>,
{
    type Item = u8;

    fn next(&mut self) -> Option<u8> {
        let byte = match self.data.next() {
            Some(item) => item,
            None => return None,
        };
        let k = self.key.next()?;
        self.pos.set(self.key.pos);
        Some(byte.borrow() ^ k)
