#[cfg(feature = "io")]
impl<W: std::io::Write> std::io::Write for XorcWriter<'_, W> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let total = buf.len();
        // Process in bounded chunks, on the stack, so that no heap allocation
        // is required and the key position only advances for bytes which have
        // actually been handed to the inner writer.
        for chunk in buf.chunks(CHUNK) {
            let mut out = [0u8; CHUNK];
            let mut len = 0;
            for (dst, src) in out.iter_mut().zip(self.xorcism.munge(chunk.iter().copied())) {
                *dst = src;
                len += 1;
            }
            self.writer.write_all(&out[..len])?;
        }
        Ok(total)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        self.writer.flush()
    }
}

//! A streaming adaptor which holds a reference to a key and bitwise-XORs it
//! with arbitrary data.
//!
//! The key is repeated as many times as necessary so that the output document
//! has the same length as the input document. Since XOR is its own inverse,
//! munging a document twice with the same key restores the original document.

use std::borrow::Borrow;
use std::cell::Cell;

/// An infinitely repeating view over a key, starting at a given offset.
///
/// This is the helper shared by [`Xorcism::munge`] and [`Xorcism::munge_in_place`]
/// so that the key indexing/rotation logic is written exactly once. It never
/// allocates.
#[derive(Clone)]
struct KeyStream<'a> {
    key: &'a [u8],
    pos: usize,
}

impl<'a> KeyStream<'a> {
    fn new(key: &'a [u8], pos: usize) -> Self {
        KeyStream { key, pos }
    }
}

impl<'a> Iterator for KeyStream<'a> {
    type Item = u8;

    fn next(&mut self) -> Option<u8> {
        let len = self.key.len();
        let byte = self.key[self.pos];
        self.pos = if self.pos + 1 == len { 0 } else { self.pos + 1 };
        Some(byte)
    }
}

/// A munger which XORs a key with some data
#[derive(Clone)]
pub struct Xorcism<'a> {
    /// The key, borrowed (never copied) from the caller.
    key: &'a [u8],
    /// Position of the next key byte. A `Cell` so that the iterator returned by
    /// `munge` can keep advancing it through a shared reference.
    pos: Cell<usize>,
}

impl<'a> Xorcism<'a> {
    /// Create a new Xorcism munger from a key
    ///
    /// Should accept anything which has a cheap conversion to a byte slice.
    pub fn new<Key>(key: &'a Key) -> Xorcism<'a>
    where
        Key: AsRef<[u8]> + ?Sized,
    {
        let key = key.as_ref();
        assert!(!key.is_empty(), "cannot munge with an empty key");
        Xorcism {
            key,
            pos: Cell::new(0),
        }
    }

    /// A key stream beginning at the current position.
    fn stream(&self) -> KeyStream<'a> {
        KeyStream::new(self.key, self.pos.get())
    }

    /// XOR each byte of the input buffer with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    pub fn munge_in_place(&mut self, data: &mut [u8]) {
        let mut key = self.stream();
        for (byte, k) in data.iter_mut().zip(&mut key) {
            *byte ^= k;
        }
        self.pos.set(key.pos);
    }

    /// XOR each byte of the data with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    ///
    /// Should accept anything which has a cheap conversion to a byte iterator.
    /// Shouldn't matter whether the byte iterator's values are owned or borrowed.
    pub fn munge<Data>(&mut self, data: Data) -> impl Iterator<Item = u8>
    where
        Data: IntoIterator,
        Data::Item: Borrow<u8>,
    {
        Munge {
            key: self.stream(),
            pos: &self.pos,
            data: data.into_iter(),
        }
    }

    /// Convert this Xorcism into a `Read` adaptor which XORs everything read
    /// from the underlying reader.
    #[cfg(feature = "io")]
    pub fn reader<R>(self, reader: R) -> XorcReader<'a, R>
    where
        R: std::io::Read,
    {
        XorcReader {
            xorcism: self,
            reader,
        }
    }

    /// Convert this Xorcism into a `Write` adaptor which XORs everything
    /// written before handing it to the underlying writer.
    #[cfg(feature = "io")]
    pub fn writer<W>(self, writer: W) -> XorcWriter<'a, W>
    where
        W: std::io::Write,
    {
        XorcWriter {
            xorcism: self,
            writer,
        }
    }
}

/// The iterator returned by [`Xorcism::munge`].
struct Munge<'x, 'a, Data>
where
    Data: Iterator,
    Data::Item: Borrow<u8>,
{
    /// Lazily repeating key, starting where `pos` last left off.
    key: KeyStream<'a>,
    /// Shared with the [`Xorcism`] this iterator was created from, so that the
    /// key position survives (and is consistent with) partial consumption.
    pos: &'x Cell<usize>,
    data: Data,
}

impl<'x, 'a, Data> Iterator for Munge<'x, 'a, Data>
where
    Data: Iterator,
    Data::Item: Borrow<u8>,
{
    type Item = u8;

    fn next(&mut self) -> Option<u8> {
        let item = self.data.next()?;
        let k = self.key.next()?;
        self.pos.set(self.key.pos);
        Some(item.borrow() ^ k)
    }
}

/// A `Read` adaptor which XORs the bytes it reads.
#[cfg(feature = "io")]
pub struct XorcReader<'a, R> {
    xorcism: Xorcism<'a>,
    reader: R,
}

#[cfg(feature = "io")]
impl<R: std::io::Read> std::io::Read for XorcReader<'_, R> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let n = self.reader.read(buf)?;
        if n > 0 {
            self.xorcism.munge_in_place(&mut buf[..n]);
        }
        Ok(n)
    }
}

/// A `Write` adaptor which XORs the bytes it is given.
#[cfg(feature = "io")]
pub struct XorcWriter<'a, W> {
    xorcism: Xorcism<'a>,
    writer: W,
}

/// Size of the stack buffer used by [`XorcWriter`].
#[cfg(feature = "io")]
const CHUNK: usize = 512;

#[cfg(feature = "io")]
impl<W: std::io::Write> std::io::Write for XorcWriter<'_, W> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let total = buf.len();
        // Process the input in bounded, stack-allocated chunks so that no heap
        // allocation is needed and the key position only advances for bytes
        // which have actually been handed to the inner writer.
        for chunk in buf.chunks(CHUNK) {
            let mut out = [0u8; CHUNK];
            let mut len = 0;
            for (dst, src) in out.iter_mut().zip(self.xorcism.munge(chunk.iter().copied())) {
                *dst = src;
                len += 1;
            }
            self.writer.write_all(&out[..len])?;
        }
        Ok(total)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        self.writer.flush()
    }
}
